!function(){"use strict";function clienteCtrl($scope,clienteSvc,tS,commonSvc){$scope.recordsQuantity=[10,25,50,100],$scope.dataSearch={pageIndex:1,pageSize:50,maxSize:5},$scope.onKeyupSearchCliente=function(){$scope.getClientes()},$scope.refresh=function(){$scope.dataSearch.textSearch=null,$scope.getClientes()},$scope.pagechanged=function(){$scope.getClientes()},$scope.changePageSize=function(){$scope.dataSearch.pageIndex=1,$scope.getClientes()},$scope.getClientes=function(){try{showLoader(),$scope.clientes=[];const dataSearch={pageIndex:$scope.dataSearch.pageIndex,pageSize:$scope.dataSearch.pageSize,checkTextSearch:!!$scope.dataSearch.textSearch,textSearch:$scope.dataSearch.textSearch};clienteSvc.getAll(dataSearch).then(response=>{hideLoader(),$scope.clientes=response,$scope.dataSearch.totalRecords=$scope.clientes.length>0?$scope.clientes[0].totalRecords:0,console.log($scope.dataSearch)}).catch(error=>{$scope.dataSearch.totalRecords=0,console.log(error),hideLoader()})}catch(error){$scope.dataSearch.totalRecords=0,console.log(error),hideLoader()}},$scope.getClientes(),$scope.resultModal=function(item){try{"object"==typeof item&&$scope.getClientes()}catch(err){console.log(err)}},$scope.askToDelete=async function(item){try{let{isConfirmed:isConfirmed}=await Swal.fire({html:`<small>Esta Ud. seguro de Inactivar al Cliente <b>${item.nombreFiscal}</b></small>?`,icon:"warning",showConfirmButton:!0,confirmButtonText:"Sí, inactivar!",showCancelButton:!0,cancelButtonText:"No, cancelar!",allowOutsideClick:!1});isConfirmed&&(showLoader(),clienteSvc.delete(item.idCliente).then(response=>{hideLoader(),"0"===response.code&&tS.toastr("warning",response.message,response.titleSms),"1"===response.code&&(tS.toastr("success",response.message,response.titleSms),$scope.getClientes())}).catch(error=>{hideLoader(),console.log(error)}))}catch(e){hideLoader(),console.log(e)}},$scope.getReport=function(format){let dataParms={tipo:4};const parameters={hasService:!1,reportParams:JSON.stringify({hasParams:!1,codigo:"RCL",format:format,aditionalParams:[]}),dataParams:JSON.stringify(dataParms)};commonSvc.getReport({parameters:parameters,formatType:format})}}app.controller("clienteCtrl",clienteCtrl),clienteCtrl.$inject=["$scope","clienteService","toastService","commonService"]}(window.angular);